window.TEXTOS_SEED["eclesiastico"][6] = [
{s:"A verdadeira e a falsa amizade"},
{v:1,l:["Não prejudiques ninguém, nem pouco nem muito,","e não te tornes inimigo em vez de amigo;","pois herdarás má fama, vergonha e desprezo:","assim acontece a todo pecador invejoso e de língua dobre."]},
{v:2,l:["Não te exaltes nos pensamentos da tua alma como um touro,","para que a tua força não seja despedaçada pela tua insensatez,"],np:1},
{v:3,l:["e ela não coma as tuas folhas, não destrua os teus frutos,","e não fiques como uma árvore seca no deserto."],np:1},
{v:4,l:["Pois a alma perversa perde quem a possui,","o torna motivo de alegria para os inimigos","e o conduz à sorte dos ímpios."],np:1},
{v:5,l:["A palavra amável multiplica os amigos e acalma os inimigos,","e a língua graciosa atrai saudações."],np:1},
{v:6,l:["Sejam muitos os que vivem em paz contigo,","mas o teu conselheiro seja um entre mil."],np:1},
{v:7,l:["Se adquires um amigo, adquire-o pondo-o à prova,","e não confies nele depressa."],np:1},
{v:8,l:["Pois há amigos de ocasião,","que não permanecerão no dia da tribulação."],np:1},
{v:9,l:["Há amigos que se tornam inimigos","e divulgam as vossas brigas, para te humilhar."],np:1},
{v:10,l:["Há amigos companheiros de mesa,","que não permanecerão no dia da necessidade;"],np:1},
{v:11,l:["na prosperidade serão como tu mesmo","e agirão com familiaridade entre os de tua casa;"],np:1},
{v:12,l:["mas, se fores humilhado, se voltarão contra ti","e se esconderão da tua presença."],np:1},
{v:13,l:["Afasta-te dos teus inimigos","e toma cuidado com os teus amigos."],np:1},
{v:14,l:["O amigo fiel é uma proteção poderosa;","quem o encontra encontrou um tesouro."],np:1},
{v:15,l:["O amigo fiel não tem preço,","e o seu valor não se pode pesar."],np:1},
{v:16,l:["O amigo fiel é um remédio de vida,","e os que temem o Senhor o encontrarão."],np:1},
{v:17,l:["Quem teme a Deus terá também uma amizade igual,","pois o seu amigo será como ele."],np:1},
{s:"O caminho da sabedoria"},
{v:18,l:["Filho, desde a juventude acolhe a instrução,","e até os cabelos brancos encontrarás a sabedoria."]},
{v:19,l:["Aproxima-te dela como quem lavra e semeia,","e espera os seus bons frutos."],np:1},
{v:20,l:["Pois no seu cultivo te cansarás pouco,","e logo comerás dos seus frutos."],np:1},
{v:21,l:["Como ela é áspera para os ignorantes!","O insensato não permanecerá nela."],np:1},
{v:22,l:["Será para ele como uma pedra pesada de prova,","e ele não tardará em rejeitá-la."],np:1},
{v:23,l:["Pois a sabedoria corresponde ao seu nome","e não se manifesta a muitos;","mas para aqueles que a conhecem ela permanece até a presença de Deus."],np:1,n:"No hebraico há um jogo de palavras: musar significa instrução e também coisa afastada."},
{v:24,l:["Escuta, filho, e acolhe o meu parecer,","não rejeites o meu conselho."],np:1},
{v:25,l:["Mete os pés nos seus grilhões","e o pescoço na sua coleira;"],np:1},
{v:26,l:["põe o ombro debaixo dela e carrega-a,","e não te irrites com os seus laços."],np:1},
{v:27,l:["Aproxima-te dela com toda a tua alma","e guarda os seus caminhos com todas as tuas forças."],np:1},
{v:28,l:["Investiga e procura, busca e a encontrarás;","e, quando a tiveres alcançado, não a deixes."],np:1},
{v:29,l:["Pois no fim encontrarás nela o repouso,","e ela se transformará para ti em alegria."],np:1},
{v:30,l:["Os seus grilhões serão para ti uma proteção poderosa,","e a sua coleira, uma veste de glória;"],np:1},
{v:31,l:["pois nela há uma beleza de ouro,","e os seus laços são fitas de púrpura."],np:1},
{v:32,l:["Tu a vestirás como uma veste de glória","e a porás sobre a cabeça como coroa de alegria."],np:1},
{v:33,l:["Filho, se prestares atenção, aprenderás;","e, se aplicares o espírito, serás prudente."],np:1},
{v:34,l:["Se gostares de ouvir, receberás a instrução;","e, se inclinares o ouvido, serás sábio."],np:1},
{v:35,l:["Frequenta a assembleia dos anciãos","e une-te de coração à sua sabedoria,","para que queiras ouvir todo discurso sobre Deus","e não te escapem as máximas da inteligência."],np:1},
{v:36,l:["Se vires um homem sensato, madruga para ir ter com ele,","e que o teu pé gaste os degraus da sua porta."],np:1},
{v:37,l:["Medita nos preceitos de Deus","e ocupa-te sem cessar com os seus mandamentos;","ele mesmo firmará o teu coração,","e te será dado o desejo da sabedoria."],np:1}
];

