{v:25,l:["Quem louvará o Altíssimo na morada dos mortos,","em lugar dos vivos que lhe dão graças?"],np:1},
{v:26,l:["Não permaneças no erro dos ímpios;","louva a Deus antes da morte:","para o morto, como quem já não existe, cessa o louvor."],np:1},
{v:27,l:["Louvarás enquanto viveres; vivo e com saúde o louvarás,","glorificarás a Deus e te gloriarás na sua misericórdia."],np:1},
{v:28,l:["Como é grande a misericórdia do Senhor","e o seu perdão para os que se convertem a ele!"],np:1},
{v:29,l:["Pois o homem não pode ter tudo,","porque o filho do homem não é imortal."],np:1},
{v:30,l:["Que há de mais brilhante que o sol? E também ele se eclipsa.","Que há de mais perverso do que os pensamentos da carne e do sangue?","Também isso será julgado."],np:1},
{v:31,l:["Ele vigia o exército do alto do céu,","e todos os homens são terra e cinza."],np:1}
